// TuiMain.swift - the body of Warden.app: a "bring the TUI to the front"
// widget.  Generated by `repl-kit app init`.
//
// Why a real app instead of an `osacompile` AppleScript applet:
//   an applet only has run / open / reopen / idle / quit - there is no
//   `activate`.  Clicking the Dock icon (reopen) works, but Command-Tab
//   (activate) does nothing and leaves an empty window on top.  A real app has
//   applicationDidBecomeActive, so both paths finally behave the same.
//
// This process implements *no* window logic.  Find-or-create-or-focus all lives
// in warden-summon.applescript, which is the single source of truth and can be run on its
// own with `osascript`.
import Cocoa

// `repl-kit app init` substituted the real repository path here.
let REPO = "/Users/a67_68/projects/ti_extend"

final class AppDelegate: NSObject, NSApplicationDelegate {
    private let queue = DispatchQueue(label: "warden.summon")
    private let lock = NSLock()
    private var busy = false
    private var lastAt = Date.distantPast

    // Command-Tab back into the app - the event an applet cannot receive.
    func applicationDidBecomeActive(_ notification: Notification) {
        summon(reason: "becomeActive")
    }

    // Dock click / `open -a` / Finder double-click.
    func applicationShouldHandleReopen(_ sender: NSApplication, hasVisibleWindows flag: Bool) -> Bool {
        summon(reason: "reopen")
        return false
    }

    // There are no windows, so "all windows closed" must not mean "quit".
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        return false
    }

    // Also summon on launch.  Hung on applicationDidBecomeActive *alone* is not
    // enough: when `open` is called from the background (a terminal, a script,
    // an automation tool) the app is not necessarily activated, and that path
    // ends up "started but nothing happened".  Both hooks fire; the debounce
    // below deduplicates them.
    //
    // Side effect: adding this app to Login Items pops the TUI up on boot.
    // Set WARDEN_QUIET_LAUNCH=1 on the login item to suppress it.
    func applicationDidFinishLaunching(_ notification: Notification) {
        if ProcessInfo.processInfo.environment["WARDEN_QUIET_LAUNCH"] == "1" {
            log("launched (WARDEN_QUIET_LAUNCH=1, not summoning)")
            return
        }
        log("launched")
        summon(reason: "launch")
    }

    private func summon(reason: String) {
        lock.lock()
        let now = Date()
        if busy {
            lock.unlock()
            log("skip \(reason): previous summon still running")
            return
        }
        // Debounce, for two reasons:
        //   1) didFinishLaunching -> didBecomeActive arrive back to back
        //   2) after we activate the terminal, the system may hand activation
        //      back to us about a second later; that must not push a second
        //      refresh into the TUI.
        if now.timeIntervalSince(lastAt) < 1.5 {
            lock.unlock()
            log("skip \(reason): less than 1.5s since the last summon")
            return
        }
        busy = true
        lastAt = now
        lock.unlock()

        queue.async { [weak self] in
            guard let self = self else { return }
            self.runSummon(reason: reason)
            self.lock.lock()
            self.busy = false
            self.lock.unlock()
        }
    }

    private func runSummon(reason: String) {
        let script = REPO + "/app/warden-summon.applescript"
        guard FileManager.default.fileExists(atPath: script) else {
            log("missing \(script) - repo moved? rerun `repl-kit app init`")
            return
        }
        log("summon (\(reason)) -> \(script)")

        let proc = Process()
        proc.executableURL = URL(fileURLWithPath: "/usr/bin/osascript")
        proc.arguments = [script]
        let pipe = Pipe()
        proc.standardOutput = pipe
        proc.standardError = pipe
        do {
            try proc.run()
        } catch {
            log("cannot start osascript: \(error)")
            return
        }
        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        proc.waitUntilExit()
        let out = (String(data: data, encoding: .utf8) ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        log("osascript exited \(proc.terminationStatus): \(out)")
    }

    private func log(_ msg: String) {
        let stamp = ISO8601DateFormatter().string(from: Date())
        let line = "\(stamp) [app] \(msg)\n"
        let path = REPO + "/temp/warden-app.log"
        try? FileManager.default.createDirectory(
            atPath: (path as NSString).deletingLastPathComponent,
            withIntermediateDirectories: true)
        if let handle = FileHandle(forWritingAtPath: path) {
            handle.seekToEndOfFile()
            handle.write(Data(line.utf8))
            try? handle.close()
        } else {
            try? line.write(toFile: path, atomically: true, encoding: .utf8)
        }
    }
}

// MARK: - entry point

let app = NSApplication.shared
let delegate = AppDelegate()
app.delegate = delegate
// .regular = shows up in the Dock and in Command-Tab, which is the whole point.
app.setActivationPolicy(.regular)

// Minimal menu bar: a windowless app still needs Command-Q.
let mainMenu = NSMenu()
let appMenuItem = NSMenuItem()
mainMenu.addItem(appMenuItem)
let appMenu = NSMenu()
appMenu.addItem(withTitle: "关于 Warden",
                action: #selector(NSApplication.orderFrontStandardAboutPanel(_:)),
                keyEquivalent: "")
appMenu.addItem(NSMenuItem.separator())
appMenu.addItem(withTitle: "退出 Warden",
                action: #selector(NSApplication.terminate(_:)),
                keyEquivalent: "q")
appMenuItem.submenu = appMenu
app.mainMenu = mainMenu

app.run()
